void getKeysSubcommand(client *c) {
    struct redisCommand *cmd = NULL;
    struct redisCommand *base_cmd = NULL;
    getKeysResult result = GETKEYS_RESULT_INIT;
    robj **cmd_argv;
    int cmd_offset = 2;
    int cmd_argc;
    int j, nkeys = 0;
    int *keys;
    int module_cmd;

    cmd_argv = c->argv + cmd_offset;
    cmd_argc = c->argc - cmd_offset;

    if (cmd_argc >= 1) {
        base_cmd = dictFetchValue(server.commands, cmd_argv[0]->ptr);
        if (cmd_argc == 1) {
            cmd = base_cmd;
        } else {
            if (base_cmd != NULL) {
                if (base_cmd->subcommands_dict != NULL) {
                    dict *subdict = base_cmd->subcommands_dict;
                    sds subname = cmd_argv[1]->ptr;
                    cmd = dictFetchValue(subdict, subname);
                } else {
                    cmd = base_cmd;
                }
            } else {
                cmd = base_cmd;
            }
        }
    }

    if (!cmd) {
        addReplyError(c,"Invalid command specified");
        return;
    } else if (cmd->getkeys_proc == NULL && cmd->key_specs_num == 0) {
        addReplyError(c,"The command has no key arguments");
        return;
    } else if ((cmd->arity > 0 && cmd->arity != cmd_argc) ||
               (cmd_argc < -cmd->arity))
    {
        addReplyError(c,"Invalid number of arguments specified for command");
        return;
    }

    module_cmd = (cmd->flags & CMD_MODULE) != 0;
    if (!module_cmd) {
        if (cmd->getkeys_proc == evalGetKeys) {
            int keyCountOfs = 2;
            int firstKeyOfs = 3;
            int keyStep = 1;
            int num;
            int maxkeys;
            num = atoi(cmd_argv[keyCountOfs]->ptr);
            maxkeys = (cmd_argc - firstKeyOfs) / keyStep;
            if (num < 1 || num > maxkeys) {
                result.numkeys = 0;
                nkeys = 0;
            } else {
                int pos;
                keys = getKeysPrepareResult(&result, num);
                result.numkeys = num;
                for (j = 0; j < num; j++) {
                    pos = firstKeyOfs + (j * keyStep);
                    keys[j] = pos;
                }
                nkeys = result.numkeys;
            }
        } else {
            nkeys = getKeysFromCommand(cmd, cmd_argv, cmd_argc, &result);
        }
    } else {
        nkeys = getKeysFromCommand(cmd, cmd_argv, cmd_argc, &result);
    }

    if (!nkeys) {
        addReplyError(c,"Invalid arguments specified for command");
    } else {
        int keypos;
        robj *keyobj;
        size_t keylen;
        addReplyLongLongWithPrefix(c, result.numkeys, '*');
        for (j = 0; j < result.numkeys; j++) {
            keypos = result.keys[j];
            keyobj = cmd_argv[keypos];
            serverAssertWithInfo(NULL,keyobj,keyobj->type == OBJ_STRING);
            if (keyobj->encoding == OBJ_ENCODING_INT) {
                keylen = sdigits10((long)keyobj->ptr);
            } else {
                keylen = sdslen(keyobj->ptr);
            }
            addReplyLongLongWithPrefix(c, keylen, '$');
            addReply(c, keyobj);
            addReply(c, shared.crlf);
        }
    }
    getKeysFreeResult(&result);
}

